"""Regression tests for metadata generated by the upstream PR workflow."""

from __future__ import annotations

import json
import os
import subprocess
from pathlib import Path

import yaml
from jinja2 import Environment, FileSystemLoader, StrictUndefined

REPO = Path(__file__).resolve().parent.parent


def _render_workflow() -> dict:
    registry = yaml.safe_load((REPO / "providers.yml").read_text(encoding="utf-8"))
    providers = [
        provider
        for provider in registry["providers"]
        if provider.get("provider_type") != "server_fork"
    ]
    base = providers[0]
    env = Environment(
        loader=FileSystemLoader(str(REPO / "wrappers")),
        undefined=StrictUndefined,
        keep_trailing_newline=True,
    )
    rendered = env.get_template("upstream-pr.yml.j2").render(
        domain=base["domain"],
        display_name=base["display_name"],
        manifest_path=base["manifest_path"],
        provider_path=base["provider_path"],
        provider_type=base["provider_type"],
        locale=base.get("locale", "en"),
        repo=base["repo"],
        default_branch=base["default_branch"],
        service_url=base.get("service_url", ""),
        auth_method=base.get("auth_method", ""),
        max_quality=base.get("max_quality", ""),
        features=base.get("features", []),
        codespell_ignore_words=base.get("codespell_ignore_words", ""),
        github_description=base.get("github_description", ""),
        github_topics=base.get("github_topics", []),
        github_homepage=base.get("github_homepage", ""),
        related_providers=base.get("related_providers", []),
        all_providers=providers,
    )
    return yaml.safe_load(rendered)


def _render_workflow_script() -> str:
    workflow = _render_workflow()
    steps = workflow["jobs"]["create-upstream-pr"]["steps"]
    return next(
        step["run"]
        for step in steps
        if step.get("name")
        == "Prepare upstream/<domain> branch and create/update draft PR"
    )


def _fragment(script: str, start: str, end: str) -> str:
    return script.split(start, 1)[1].split(end, 1)[0]


def _run_shell(fragment: str, **environment: str) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        ["bash", "-euo", "pipefail", "-c", fragment],
        env={**os.environ, **environment},
        capture_output=True,
        text=True,
        check=False,
    )


def test_release_title_is_user_facing() -> None:
    """A conventional-commit prefix must not break upstream PR metadata checks."""
    script = _render_workflow_script()
    fragment = _fragment(script, "# Generate PR title", "# Get changelog data")
    fragment = fragment.replace("${{ inputs.pr_summary }}", "$PR_SUMMARY_INPUT")
    result = _run_shell(
        fragment + '\nprintf "%s" "$PR_TITLE"',
        DOMAIN="yandex_music",
        DISPLAY_NAME="Yandex Music",
        VERSION="v3.8.8",
        PREV_TAG="v3.8.7",
        PR_SUMMARY_INPUT="shared playlist requests",
    )

    assert result.returncode == 0, result.stderr
    assert result.stdout == (
        "Update Yandex Music provider to v3.8.8: shared playlist requests"
    )


def test_body_selects_one_type_and_confirms_completed_checks() -> None:
    """Generated metadata must satisfy upstream's label and checklist contracts."""
    script = _render_workflow_script()
    fragment = _fragment(
        script,
        '# Determine which "Types of changes" box gets ticked. Upstream accepts exactly',
        "# Defense-in-depth",
    )
    fragment = fragment.replace("${{ inputs.change_type }}", "$CHANGE_TYPES_INPUT")
    result = _run_shell(
        fragment + '\nprintf "%s" "$PR_BODY"',
        CHANGE_TYPES_INPUT="bugfix,maintenance,dependencies",
        PREV_TAG="v3.8.7",
        DISPLAY_NAME="Yandex Music",
        VERSION="v3.8.8",
        PROVIDER_REPO="trudenboy/ma-provider-yandex-music",
        COMPARE_LABEL="vs v3.8.7",
        WHAT_NEW="- Fix playlist request sharing",
        FILES_SECTION="_No files changed_",
        HUMAN_COAUTHORS="",
    )

    assert result.returncode == 0, result.stderr
    assert result.stdout.count("- [x]") == 5
    assert "- [x] Bugfix" in result.stdout
    assert "- [ ] Maintenance / chore" in result.stdout
    assert "- [ ] Dependencies bump" in result.stdout
    assert "- [x] The code change is tested and works locally." in result.stdout
    assert "- [x] `pre-commit run --all-files` passes." in result.stdout
    assert "- [x] `pytest` passes" in result.stdout
    assert "- [x] I have read and complied with the project's [AI Policy]" in result.stdout


def test_method_order_baseline_is_not_changed_by_provider_submission() -> None:
    """Provider submissions must not rewrite upstream's repository-wide baseline."""
    script = _render_workflow_script()
    assert "scripts.check_method_order --update-baseline" not in script


def test_workflow_uses_upstream_python_version_for_metadata_tools() -> None:
    """Python syntax newer than the runner default must not be skipped by baseline tools."""
    steps = _render_workflow()["jobs"]["create-upstream-pr"]["steps"]

    setup = next(step for step in steps if step.get("name") == "Set up Python")
    assert setup["uses"].startswith("actions/setup-python@")
    assert setup["with"]["python-version-file"] == ".python-version"


def _resolve_script() -> str:
    steps = _render_workflow()["jobs"]["create-upstream-pr"]["steps"]
    return next(
        step["run"] for step in steps if step.get("name") == "Resolve domain and clone provider release"
    )


def test_version_file_shipping_is_opt_out_per_provider() -> None:
    """Providers flagged upstream_exclude_version never ship VERSION upstream."""
    resolve = _resolve_script()
    registry = yaml.safe_load((REPO / "providers.yml").read_text(encoding="utf-8"))
    for provider in registry["providers"]:
        if provider.get("provider_type") == "server_fork":
            continue
        expected = "false" if provider.get("upstream_exclude_version") else "true"
        case_line = next(
            line for line in resolve.splitlines() if line.strip().startswith(f"{provider['domain']})")
        )
        assert f'UPSTREAM_SHIP_VERSION="{expected}"' in case_line, provider["domain"]
    assert 'echo "UPSTREAM_SHIP_VERSION=$UPSTREAM_SHIP_VERSION" >> $GITHUB_ENV' in resolve


def test_version_copy_respects_opt_out(tmp_path: Path) -> None:
    """The VERSION copy step is skipped when the provider opted out."""
    script = _render_workflow_script()
    fragment = _fragment(script, "# Copy VERSION file alongside manifest", "# Regenerate requirements_all.txt")
    (tmp_path / "provider-repo").mkdir()
    (tmp_path / "provider-repo" / "VERSION").write_text("1.0.0\n")
    dest = tmp_path / "music_assistant" / "providers" / "demo"
    dest.mkdir(parents=True)

    for ship, exists in (("false", False), ("true", True)):
        result = subprocess.run(
            ["bash", "-euo", "pipefail", "-c", "#" + fragment],
            env={**os.environ, "DOMAIN": "demo", "UPSTREAM_SHIP_VERSION": ship},
            cwd=tmp_path,
            capture_output=True,
            text=True,
            check=False,
        )
        assert result.returncode == 0, result.stderr
        assert (dest / "VERSION").exists() is exists, ship


_RELEASES = [
    # GitHub lists drafts first; stale drafts must not become the compare base.
    {"tag_name": "v1.0.0", "draft": True, "prerelease": False},
    {"tag_name": "v1.0.0", "draft": True, "prerelease": False},
    {"tag_name": "v1.6.0b1", "draft": False, "prerelease": True},
    {"tag_name": "v1.5.23", "draft": False, "prerelease": False},
    {"tag_name": "v1.5.22", "draft": False, "prerelease": False},
    {"tag_name": "v1.5.9", "draft": False, "prerelease": False},
]


def _resolve_prev_tag(tmp_path: Path, version: str, releases: list[dict]) -> str:
    """Run the PREV_TAG lookup against a fake ``gh api`` serving ``releases``."""
    fixture = tmp_path / "releases.json"
    fixture.write_text(json.dumps(releases), encoding="utf-8")
    fake_gh = tmp_path / "gh"
    fake_gh.write_text(
        '#!/usr/bin/env bash\n'
        'expr=""\n'
        'while [[ $# -gt 0 ]]; do [[ "$1" == "--jq" ]] && expr="$2"; shift; done\n'
        'jq -r "$expr" "$RELEASES_FIXTURE"\n',
        encoding="utf-8",
    )
    fake_gh.chmod(0o755)
    fragment = "CURRENT_TAG=" + _fragment(_resolve_script(), "CURRENT_TAG=", 'echo "PREV_TAG=')
    fragment = fragment.replace("${{ inputs.version }}", "$INPUT_VERSION")
    result = _run_shell(
        fragment + '\nprintf "%s" "$PREV_TAG"',
        PATH=f"{tmp_path}:{os.environ['PATH']}",
        RELEASES_FIXTURE=str(fixture),
        PROVIDER_REPO="trudenboy/ma-provider-yandex-station",
        INPUT_VERSION=version,
    )
    assert result.returncode == 0, result.stderr
    return result.stdout


def test_prev_tag_skips_drafts_and_prereleases(tmp_path: Path) -> None:
    """The compare base is the newest published stable release before VERSION."""
    assert _resolve_prev_tag(tmp_path, "1.5.23", _RELEASES) == "v1.5.22"


def test_prev_tag_orders_by_version_not_listing(tmp_path: Path) -> None:
    """Re-submitting an older release compares against the release right below it."""
    assert _resolve_prev_tag(tmp_path, "1.5.22", _RELEASES) == "v1.5.9"


def test_prev_tag_is_empty_for_first_release(tmp_path: Path) -> None:
    """No earlier published release means a first-time (new-provider) submission."""
    releases = [{"tag_name": "v1.0.0", "draft": False, "prerelease": False}]
    assert _resolve_prev_tag(tmp_path, "1.0.0", releases) == ""


def _whats_new(tmp_path: Path, subjects: list[str]) -> str:
    """Run the "What's new" lookup against a fake ``gh api`` compare response."""
    fixture = tmp_path / "compare.json"
    fixture.write_text(
        json.dumps({"commits": [{"commit": {"message": s + "\n\nbody"}} for s in subjects], "files": []}),
        encoding="utf-8",
    )
    fake_gh = tmp_path / "gh"
    fake_gh.write_text(
        '#!/usr/bin/env bash\n'
        'expr=""\n'
        'while [[ $# -gt 0 ]]; do [[ "$1" == "--jq" ]] && expr="$2"; shift; done\n'
        'jq -r "$expr" "$COMPARE_FIXTURE"\n',
        encoding="utf-8",
    )
    fake_gh.chmod(0o755)
    fragment = _fragment(_render_workflow_script(), "# Get changelog data from GitHub API\n", "# Carry HUMAN co-author")
    result = _run_shell(
        fragment + '\nprintf "%s" "$WHAT_NEW"',
        PATH=f"{tmp_path}:{os.environ['PATH']}",
        COMPARE_FIXTURE=str(fixture),
        PROVIDER_REPO="trudenboy/ma-provider-msx-bridge",
        PREV_TAG="v1.6.2",
        VERSION="v1.6.3",
    )
    assert result.returncode == 0, result.stderr
    return result.stdout


def test_whats_new_includes_scoped_and_breaking_commits(tmp_path: Path) -> None:
    """Scoped (`fix(scope):`) and breaking (`feat!:`) subjects are listed (issue #182)."""
    subjects = [
        "fix(msx): restore search controls",
        "feat!: drop legacy playback path",
        "feat(player)!: new queue API",
        "fix: plain fix",
        "chore(release): Yandex Station 1.6.3",
        "docs(readme): explain setup",
        "fixup: not a conventional fix",
    ]
    assert _whats_new(tmp_path, subjects).splitlines() == [
        "- fix(msx): restore search controls",
        "- feat!: drop legacy playback path",
        "- feat(player)!: new queue API",
        "- fix: plain fix",
    ]


def test_whats_new_placeholder_when_no_feat_or_fix(tmp_path: Path) -> None:
    """A range with no feat/fix commits keeps the explicit placeholder."""
    assert _whats_new(tmp_path, ["chore: bump", "docs(readme): typo"]) == "_No feat/fix commits found_"


def _git(cwd: Path, *args: str) -> None:
    subprocess.run(["git", "-C", str(cwd), *args], check=True, capture_output=True)


def _submit_decision(tmp_path: Path, *, branch_has_release: bool, provider_text: str):
    """
    Run the "anything to submit?" decision in a scratch repo.

    ``upstream/dev`` carries provider v1; the branch HEAD optionally already
    carries v2 (as the pipeline's sync-upstream job leaves it); the working
    tree then receives ``provider_text`` as the release being submitted.
    """
    repo = tmp_path / "fork"
    dest = repo / "music_assistant" / "providers" / "demo"
    dest.mkdir(parents=True)
    _git(repo, "init", "-q", "-b", "main")
    _git(repo, "config", "user.email", "t@t")
    _git(repo, "config", "user.name", "t")
    (dest / "provider.py").write_text("v1\n")
    (repo / "unrelated.txt").write_text("upstream\n")
    _git(repo, "add", "-A")
    _git(repo, "commit", "-q", "-m", "upstream dev")
    _git(repo, "update-ref", "refs/remotes/upstream/dev", "HEAD")
    if branch_has_release:
        (dest / "provider.py").write_text("v2\n")
        _git(repo, "commit", "-q", "-am", "sync provider v2")
    (dest / "provider.py").write_text(provider_text)

    script = _render_workflow_script()
    fragment = "git add -A\n" + _fragment(script, "\ngit add -A\n", "# Generate PR title")
    return subprocess.run(
        ["bash", "-euo", "pipefail", "-c", fragment + '\nprintf "NEEDS_COMMIT=%s" "$NEEDS_COMMIT"'],
        env={**os.environ, "DOMAIN": "demo", "VERSION": "v2", "BRANCH": "upstream/demo",
             "DEST": "music_assistant/providers/demo"},
        cwd=repo,
        capture_output=True,
        text=True,
        check=False,
    )


def test_submit_proceeds_when_pipeline_already_synced_branch(tmp_path: Path) -> None:
    """A branch already holding the release still opens/updates the PR (issue #181)."""
    result = _submit_decision(tmp_path, branch_has_release=True, provider_text="v2\n")
    assert result.returncode == 0, result.stderr
    assert result.stdout.endswith("NEEDS_COMMIT=no")


def test_submit_commits_new_release(tmp_path: Path) -> None:
    """New provider changes are committed as before."""
    result = _submit_decision(tmp_path, branch_has_release=False, provider_text="v2\n")
    assert result.returncode == 0, result.stderr
    assert result.stdout.endswith("NEEDS_COMMIT=yes")


def test_submit_stops_when_provider_matches_upstream_dev(tmp_path: Path) -> None:
    """Nothing is submitted when upstream/dev already ships this provider tree."""
    result = _submit_decision(tmp_path, branch_has_release=False, provider_text="v1\n")
    assert result.returncode == 0, result.stderr
    assert "NEEDS_COMMIT" not in result.stdout
    assert "already matches upstream/dev" in result.stdout


def test_provider_claude_md_requires_exactly_one_change_type() -> None:
    """Agent guidance must match upstream's single-label rule, as the generator does."""
    template = (REPO / "wrappers" / "CLAUDE.md.j2").read_text(encoding="utf-8")
    section = template.split("## Upstream PR Body Format", 1)[1].split("\n## ", 1)[0]

    assert "exactly one" in section
    assert "multi-tick" not in section.lower()
